-- Double-sided referral loop: each user has a shareable code; a Referrals row records a
-- successful referral (referee signed up with a referrer's code). Reward fulfillment is
-- tracked via RewardStatus and granted out-of-band (see redesign doc §4.3).
BEGIN;

ALTER TABLE public."Users"
    ADD COLUMN IF NOT EXISTS "ReferralCode" character varying(16);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_ReferralCode"
    ON public."Users" ("ReferralCode") WHERE "ReferralCode" IS NOT NULL;

CREATE TABLE IF NOT EXISTS public."Referrals" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ReferrerUserId" integer NOT NULL,
    "RefereeUserId" integer NOT NULL,
    "ReferralCode" character varying(16) NOT NULL,
    "RewardStatus" character varying(20) NOT NULL DEFAULT 'pending',
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PK_Referrals" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Referrals_Users_ReferrerUserId" FOREIGN KEY ("ReferrerUserId")
        REFERENCES public."Users" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Referrals_Users_RefereeUserId" FOREIGN KEY ("RefereeUserId")
        REFERENCES public."Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Referrals_RefereeUserId"
    ON public."Referrals" ("RefereeUserId");
CREATE INDEX IF NOT EXISTS "IX_Referrals_ReferrerUserId"
    ON public."Referrals" ("ReferrerUserId");

COMMIT;
